for expr in [('L and not R',lambda a,b:a and not b),('R and not L',lambda a,b:b and not a),('L or R',lambda a,b:a or b),('intersection',lambda a,b:a and b),('same',lambda a,b:a==b)]:
 print(expr[0],sum(expr[1](a,b) for rr,ss in zip(L,R) for a,b in zip(rr,ss)),sum(expr[1](a,b)==(o==2) for rr,ss,oo in zip(L,R,O) for a,b,o in zip(rr,ss,oo)))
# print discrepancy exact coordinates
for r in range(9):
 print(r,''.join('X' if O[r][c] else '.' for c in range(13)), ''.join('L' if L[r][c] else ('R' if R[r][c] else '.') for c in range(13)))

for name,f in [('Lonly',lambda a,b:bool(a) and not bool(b)),('Ronly',lambda a,b:bool(b) and not bool(a)),('both',lambda a,b:bool(a) and bool(b)),('union',lambda a,b:bool(a) or bool(b)),('neither',lambda a,b:not a and not b)]:
 pred=[[f(a,b) for a,b in zip(rr,ss)] for rr,ss in zip(L,R)]
 print(name,sum(map(sum,pred)),sum(pred[r][c]==bool(O[r][c]) for r in range(9) for c in range(13)))

